"""MCA: annual compliance, company changes, winding up."""

CO_DOCS = [('Certificate of incorporation', 'And current MoA and AoA.'), ('Director DSC', 'Valid DSC of the signing director.'),
           ('MCA login', 'Company or professional login, or we file through ours.')]
MCA_STEPS = [('Share details', 'You tell us what is needed and share documents. We confirm the checklist.'),
             ('Drafting', 'We prepare notices, resolutions and the MCA form for your review.'),
             ('Sign and file', 'Directors sign with DSC and we file on the MCA portal.'),
             ('Approval', 'We track approval and share the challan, approval and updated records.')]
ANNUAL_STEPS = [('Books and audit', 'Your accounts are finalised and audited.'),
                ('Board and AGM', 'We draft the board report, notices and minutes for the meetings.'),
                ('Forms', 'We prepare the annual forms from the audited figures.'),
                ('File', 'Directors sign and we file, sharing challans and acknowledgements.')]

