    b=[('Right route', 'Company to LLP, OPC to private and more.'),
       ('Continuity', 'Same business, assets and contracts.'),
       ('Approvals handled', 'Resolutions, creditor consent and MCA filings.'),
       ('Tax impact checked', 'Conditions for tax-neutral conversion explained.')],
    inc=['Choosing the conversion route', 'Board and shareholder resolutions', 'Altered MoA and AoA', 'MCA filings for the route', 'Creditor consent coordination where needed', 'Post-conversion update checklist'],
    g='MCA fees depend on the route and capital.',
